<script setup lang="ts">
import{onMounted,reactive,ref}from'vue'
import{crearProceso,exportarProcesos,listarProcesos,opcionesGeograficas,type Option,type ProcesoIntegracion,type ProcesoPayload,type TerritorialFilters}from'../services/territorial'

const rows=ref<ProcesoIntegracion[]>([]),departments=ref<Option[]>([]),provinces=ref<Option[]>([]),districts=ref<Option[]>([]),towns=ref<Option[]>([]),phases=ref<Option[]>([]),companies=ref<Option[]>([]),total=ref(0),last=ref(1),loading=ref(false),saving=ref(false),exporting=ref(false),modal=ref(false),error=ref(''),success=ref('')
const filters=reactive<TerritorialFilters>({departamento:0,provincia:0,distrito:0,centro_poblado:0,fase:0,empresa:0,page:1}),form=reactive<ProcesoPayload>({empresa_id:0,fecha:new Date().toISOString().slice(0,10),centro_poblado_id:0,observaciones:''}),location=reactive({departamento:0,provincia:0,distrito:0})
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const result=await listarProcesos(filters);rows.value=result.data;total.value=result.total;last.value=result.last_page;departments.value=result.options.departamentos;phases.value=result.options.fases;companies.value=result.options.empresas;if(!provinces.value.length)provinces.value=result.options.provincias;if(!districts.value.length)districts.value=result.options.distritos;if(!towns.value.length)towns.value=result.options.centros_poblados}catch(e){error.value=message(e)}finally{loading.value=false}}
async function cascade(level:'provincias'|'distritos'|'centros-poblados',parent:number,mode:'filter'|'form'){try{const options=parent?await opcionesGeograficas(level,parent):[];if(level==='provincias'){provinces.value=options;districts.value=[];towns.value=[];if(mode==='filter'){filters.provincia=filters.distrito=filters.centro_poblado=0}else{location.provincia=location.distrito=0;form.centro_poblado_id=0}}else if(level==='distritos'){districts.value=options;towns.value=[];if(mode==='filter'){filters.distrito=filters.centro_poblado=0}else{location.distrito=0;form.centro_poblado_id=0}}else{towns.value=options;if(mode==='filter')filters.centro_poblado=0;else form.centro_poblado_id=0}}catch(e){error.value=message(e)}}
function clear(){Object.assign(filters,{departamento:0,provincia:0,distrito:0,centro_poblado:0,fase:0,empresa:0,page:1});provinces.value=[];districts.value=[];towns.value=[];load()}
function open(){Object.assign(form,{empresa_id:0,fecha:new Date().toISOString().slice(0,10),centro_poblado_id:0,observaciones:''});Object.assign(location,{departamento:0,provincia:0,distrito:0});provinces.value=[];districts.value=[];towns.value=[];modal.value=true;error.value=''}
async function save(){if(!form.empresa_id||!form.fecha||!form.centro_poblado_id){error.value='Seleccione la EPS, fecha y centro poblado.';return}saving.value=true;try{await crearProceso({...form});success.value='Proyecto de integración registrado correctamente.';modal.value=false;await load(1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function exportExcel(){exporting.value=true;try{await exportarProcesos()}catch(e){error.value=message(e)}finally{exporting.value=false}}
function phasePercent(row:ProcesoIntegracion){return Math.min(100,Math.max(0,Math.round(((row.fase_id-1)/6)*100)))}
function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / ENKI / Integración Territorial</nav><header class="hero"><div class="mark">IT</div><div><small>ENKI · INTEGRACIÓN DE PRESTADORES</small><h1>Procesos de integración territorial</h1><p>Seguimiento de centros poblados, EPS y avance por fases.</p></div><strong>{{total}} procesos</strong><button class="excel" :disabled="exporting" @click="exportExcel">{{exporting?'Exportando…':'Exportar Excel'}}</button><button @click="open">+ Nuevo proceso</button></header><div v-if="success" class="flash good">✓ {{success}}</div><div v-if="error" class="flash bad">{{error}}</div><section class="filters"><label>Departamento<select v-model.number="filters.departamento" @change="cascade('provincias',filters.departamento,'filter')"><option :value="0">Todos</option><option v-for="item in departments" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Provincia<select v-model.number="filters.provincia" :disabled="!filters.departamento" @change="cascade('distritos',filters.provincia,'filter')"><option :value="0">Todas</option><option v-for="item in provinces" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Distrito<select v-model.number="filters.distrito" :disabled="!filters.provincia" @change="cascade('centros-poblados',filters.distrito,'filter')"><option :value="0">Todos</option><option v-for="item in districts" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Centro poblado<select v-model.number="filters.centro_poblado" :disabled="!filters.distrito"><option :value="0">Todos</option><option v-for="item in towns" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Fase<select v-model.number="filters.fase"><option :value="0">Todas</option><option v-for="item in phases" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>EPS<select v-model.number="filters.empresa"><option :value="0">Todas</option><option v-for="item in companies" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><div><button @click="load()">Consultar</button><button class="clear" @click="clear">Limpiar</button></div></section><div v-if="loading" class="empty">Cargando procesos territoriales…</div><div v-else-if="!rows.length" class="empty">No se encontraron procesos de integración.</div><section v-else class="cards"><article v-for="row in rows" :key="row.id"><header><div><small>PROCESO #{{row.id}} · {{row.fecha}}</small><h2>{{row.centro_poblado}}</h2></div><span>{{row.fase}}</span></header><div class="body"><dl><div><dt>EPS</dt><dd>{{row.empresa}}</dd></div><div><dt>Ubicación</dt><dd>{{row.distrito}}, {{row.provincia}} · {{row.departamento}}</dd></div><div><dt>Documentos</dt><dd>{{row.documentos_count??0}}</dd></div><div><dt>Asistencias</dt><dd>{{row.asistencias_count??0}}</dd></div></dl><p v-if="row.observaciones">{{row.observaciones}}</p><small>AVANCE DEL PROCESO</small><div class="progress"><i :style="{width:`${phasePercent(row)}%`}"></i></div><b class="percent">{{phasePercent(row)}}%</b></div><footer><RouterLink :to="`/modulos/integracion/territorial/procesos/${row.id}`">Ver seguimiento</RouterLink></footer></article></section><footer v-if="last>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>Página {{filters.page}} de {{last}}</span><button :disabled="filters.page>=last" @click="load(filters.page+1)">Siguiente</button></footer><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>NUEVO PROCESO TERRITORIAL</small><h2>Registrar integración de prestadores</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>EPS *<select v-model.number="form.empresa_id"><option :value="0">Seleccione</option><option v-for="item in companies" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Fecha de inicio *<input v-model="form.fecha" type="date"></label><label>Departamento *<select v-model.number="location.departamento" @change="cascade('provincias',location.departamento,'form')"><option :value="0">Seleccione</option><option v-for="item in departments" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Provincia *<select v-model.number="location.provincia" :disabled="!location.departamento" @change="cascade('distritos',location.provincia,'form')"><option :value="0">Seleccione</option><option v-for="item in provinces" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Distrito *<select v-model.number="location.distrito" :disabled="!location.provincia" @change="cascade('centros-poblados',location.distrito,'form')"><option :value="0">Seleccione</option><option v-for="item in districts" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Centro poblado *<select v-model.number="form.centro_poblado_id" :disabled="!location.distrito"><option :value="0">Seleccione</option><option v-for="item in towns" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label class="wide">Observaciones<textarea v-model.trim="form.observaciones" rows="3"></textarea></label></div><p class="notice">Un centro poblado solo puede estar asociado a un proceso de integración.</p><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Registrando…':'Registrar proceso'}}</button></footer></form></div></div></template>

<style scoped>
.page{--a:#148f92;color:#35474d}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:10px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:800}.hero small,.modal small{color:var(--a);font-size:.5rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.2rem}.hero p{margin:0;color:#7c898f;font-size:.6rem}.hero strong{margin-left:auto;font-size:.48rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 10px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.46rem}.hero .excel{color:#267359;background:#e8f6ef}.flash{padding:10px;font-size:.58rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:grid;grid-template-columns:repeat(6,1fr) auto;align-items:end;gap:6px;background:#fff}.filters label,.modal label{font-size:.44rem}input,select,textarea{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;background:#fff;font:inherit;font-size:.48rem}.clear{color:#68767c!important;background:#edf1f2!important}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:11px}.cards article{border-top:3px solid var(--a);border-radius:9px;background:#fff}.cards article>header{padding:13px;display:flex;align-items:start;border-bottom:1px solid #e8eded}.cards h2{margin:2px 0;font-size:.72rem}.cards header small{color:#89949a;font-size:.39rem}.cards header span{margin-left:auto;padding:4px 7px;border-radius:10px;color:#287275;background:#e3f3f3;font-size:.4rem}.body{padding:13px}.body dl{margin:0}.body dl div{padding:4px 0;display:flex;border-bottom:1px solid #edf0f1;font-size:.44rem}.body dt{color:#89949a}.body dd{margin-left:auto;text-align:right}.body p{color:#69777d;font-size:.44rem}.body>small{font-size:.36rem}.progress{height:6px;margin-top:4px;border-radius:4px;background:#e5ecec}.progress i{height:100%;display:block;border-radius:4px;background:var(--a)}.percent{display:block;margin-top:3px;text-align:right;font-size:.44rem}.cards article>footer{padding:0 13px 13px;text-align:right}.cards footer a{color:var(--a);font-size:.45rem}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.57rem}.pages{display:flex;justify-content:center;align-items:center;gap:9px;font-size:.47rem}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(720px,100%);max-height:94vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:.85rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.grid{margin-top:12px;display:grid;grid-template-columns:1fr 1fr;gap:8px}.wide{grid-column:span 2}.notice{padding:8px;color:#795d20;background:#fff4d8;font-size:.45rem}.modal footer{display:flex;justify-content:flex-end;gap:5px}@media(max-width:1050px){.filters{grid-template-columns:repeat(3,1fr)}.cards{grid-template-columns:1fr 1fr}}@media(max-width:650px){.hero{flex-wrap:wrap}.hero strong{margin-left:0}.filters,.cards,.grid{grid-template-columns:1fr}.wide{grid-column:auto}}
</style>
